import{_ as t,c as a,o as i,ae as r}from"./chunks/framework.Cd-3tpCq.js";const m=JSON.parse('{"title":"Attribute Families","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/catalog/families/index.md","filePath":"api/graphql-api/admin/catalog/families/index.md"}'),o={name:"api/graphql-api/admin/catalog/families/index.md"};function d(s,e,n,l,c,u){return i(),a("div",null,e[0]||(e[0]=[r('<h1 id="attribute-families" tabindex="-1">Attribute Families <a class="header-anchor" href="#attribute-families" aria-label="Permalink to &quot;Attribute Families&quot;">​</a></h1><p>An attribute family is the <strong>template of fields a product carries</strong>. Every product belongs to exactly one family, and the family decides which attributes (and in what layout) appear on that product&#39;s edit form. The Attribute Families menu lists, creates, edits, and deletes them. It mirrors the admin <strong>Catalog → Attribute Families</strong> screen.</p><h2 id="how-a-family-is-structured" tabindex="-1">How a family is structured <a class="header-anchor" href="#how-a-family-is-structured" aria-label="Permalink to &quot;How a family is structured&quot;">​</a></h2><p>A family is a set of <strong>attribute groups</strong>, and each group holds a list of <strong>attributes</strong>:</p><ul><li><strong>Groups</strong> (e.g. <code>General</code>, <code>Description</code>, <code>Meta Description</code>, <code>Price</code>, <code>Inventories</code>, <code>Images</code>) organise the edit form into sections. Each group has a <code>column</code> (1 or 2) and a <code>position</code> (order).</li><li><strong>Attributes</strong> within a group are references to entries from the <a href="/api/graphql-api/admin/catalog/attributes/">Attributes</a> menu, each with its own <code>position</code> and <code>isRequired</code> flag.</li></ul><h2 id="nested-data-is-returned-whole" tabindex="-1">Nested data is returned whole <a class="header-anchor" href="#nested-data-is-returned-whole" aria-label="Permalink to &quot;Nested data is returned whole&quot;">​</a></h2><p>On the single-family query, <code>attributeGroups</code> (each group with its nested <code>attributes</code>) is returned as <strong>whole JSON</strong> — query it as a bare field (<code>attributeGroups</code>, not <code>attributeGroups { … }</code>); the entire structure comes back, and it resolves over GraphQL. The listing is slim (<code>id</code>, <code>code</code>, <code>name</code> only) — fetch the structure by id.</p><h2 id="editing-the-structure" tabindex="-1">Editing the structure <a class="header-anchor" href="#editing-the-structure" aria-label="Permalink to &quot;Editing the structure&quot;">​</a></h2><p>Create and update accept the nested <code>attributeGroups</code> (with <code>customAttributes</code>). On update, groups are matched by id; a group keyed <code>group_*</code> is created, and an existing group id omitted from the payload is removed (and so are omitted attributes within a kept group). This mirrors the admin form&#39;s add/remove behaviour.</p><h2 id="delete-guards" tabindex="-1">Delete guards <a class="header-anchor" href="#delete-guards" aria-label="Permalink to &quot;Delete guards&quot;">​</a></h2><p>A family <strong>cannot be deleted</strong> if it is the last remaining family, or if any product is still assigned to it — both return an error. Reassign or remove those products first.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/catalog/families/families-listing.html">List families</a></td><td><code>adminAttributeFamilies</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/families/families-detail.html">Family detail</a></td><td><code>adminAttributeFamily(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/families/families-create.html">Create family</a></td><td><code>createAdminAttributeFamily</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/families/families-update.html">Update family</a></td><td><code>updateAdminAttributeFamily</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/families/families-delete.html">Delete family</a></td><td><code>deleteAdminAttributeFamily</code> mutation</td></tr></tbody></table><p>All Attribute Families operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>. Reads require <code>catalog.families.view</code>; writes require the matching <code>catalog.families.create</code> / <code>.edit</code> / <code>.delete</code> permission.</p>',14)]))}const p=t(o,[["render",d]]);export{m as __pageData,p as default};
